<?php
declare(strict_types=1);
require dirname(__DIR__) . '/bootstrap.php';
require_login(['admin']);
sokna_module_require('reporting');
require dirname(__DIR__) . '/includes/panel_layout.php';
require_once dirname(__DIR__) . '/includes/reporting.php';
require_once dirname(__DIR__) . '/includes/xlsx_export.php';

function analytics_number(mixed $value, int $decimals = 0): string {if ($value === null || $value === '') return '—';$n=number_format((float)$value,$decimals,'.','');if($decimals>0)$n=rtrim(rtrim($n,'0'),'.');return fa_digits($n);}
function analytics_scalar(PDO $pdo,string $sql,array $params=[]):mixed{$st=$pdo->prepare($sql);$st->execute($params);$v=$st->fetchColumn();return $v===false?null:$v;}
function analytics_rows(PDO $pdo,string $sql,array $params=[]):array{$st=$pdo->prepare($sql);$st->execute($params);return $st->fetchAll();}
function analytics_snapshot_filter(string $alias,string $fromDate,string $toDate,string $shiftKey=''):array{return business_snapshot_filter_sql($alias,$fromDate,$toDate,$shiftKey);}

$pdo=db();
$range=report_range_resolve('30');
$fromBusiness=(string)$range['from'];$toBusiness=(string)$range['to'];$days=(int)$range['days'];
$shiftOptions=business_report_shift_options($fromBusiness,$toBusiness,true);
$showShiftFilter=count($shiftOptions)>1;
$shiftScope=(string)($_GET['shift']??'all');if(!isset($shiftOptions[$shiftScope]))$shiftScope='all';
$selectedShift=(!in_array($shiftScope,['all','compare'],true)&&isset($shiftOptions[$shiftScope]))?$shiftScope:'';
$previousToBusiness=(new DateTimeImmutable($fromBusiness))->modify('-1 day')->format('Y-m-d');
$previousFromBusiness=(new DateTimeImmutable($previousToBusiness))->modify('-'.($days-1).' days')->format('Y-m-d');
[$physicalStart,$physicalEnd]=business_date_range_bounds($fromBusiness,$toBusiness);$from=$physicalStart->format('Y-m-d H:i:s');$to=$physicalEnd->format('Y-m-d H:i:s');
$warning=(string)$range['error'];$guestShiftLimited=$selectedShift!=='';
$validSettlement=report_valid_settlement_sql('sr');
$saleLineSource=report_settlement_line_source_sql('sale');
$settlementWhere="$validSettlement AND sr.business_date>=? AND sr.business_date<=?";$settlementParams=[$fromBusiness,$toBusiness];if($selectedShift!==''){$settlementWhere.=' AND sr.business_shift_key=?';$settlementParams[]=$selectedShift;}
$previousWhere="$validSettlement AND sr.business_date>=? AND sr.business_date<=?";$previousParams=[$previousFromBusiness,$previousToBusiness];if($selectedShift!==''){$previousWhere.=' AND sr.business_shift_key=?';$previousParams[]=$selectedShift;}

try{
    $netSales=(int)(analytics_scalar($pdo,"SELECT COALESCE(SUM(sr.total-sr.tax_amount),0) FROM settlement_records sr WHERE $settlementWhere",$settlementParams)??0);
    $taxTotal=(int)(analytics_scalar($pdo,"SELECT COALESCE(SUM(sr.tax_amount),0) FROM settlement_records sr WHERE $settlementWhere",$settlementParams)??0);
    $collectedTotal=(int)(analytics_scalar($pdo,"SELECT COALESCE(SUM(sr.total),0) FROM settlement_records sr WHERE $settlementWhere",$settlementParams)??0);
    $prevSales=(int)(analytics_scalar($pdo,"SELECT COALESCE(SUM(sr.total-sr.tax_amount),0) FROM settlement_records sr WHERE $previousWhere",$previousParams)??0);
    $receiptCount=(int)(analytics_scalar($pdo,"SELECT COUNT(*) FROM settlement_records sr WHERE $settlementWhere",$settlementParams)??0);
    $billCount=(int)(analytics_scalar($pdo,"SELECT COUNT(DISTINCT sr.session_id) FROM settlement_records sr WHERE $settlementWhere",$settlementParams)??0);
    $avgCheck=$billCount>0?(int)round($collectedTotal/$billCount):null;
    $avgSession=analytics_scalar($pdo,"SELECT AVG(TIMESTAMPDIFF(MINUTE,ts.started_at,COALESCE(ts.ended_at,sr.settled_at))) FROM settlement_records sr JOIN table_sessions ts ON ts.id=sr.session_id WHERE $settlementWhere AND COALESCE(ts.ended_at,sr.settled_at)>=ts.started_at",$settlementParams);
    $tableCount=(int)(analytics_scalar($pdo,"SELECT COUNT(*) FROM cafe_tables WHERE active=1")??0);
    // Concurrent-table pressure cannot be truthfully scoped to a historical shift from the current session schema.
    $peakTables=$selectedShift===''?(int)(analytics_scalar($pdo,"SELECT COALESCE(MAX((SELECT COUNT(*) FROM table_sessions t2 WHERE t2.started_at<=t1.started_at AND COALESCE(t2.ended_at,?)>t1.started_at)),0) FROM table_sessions t1 WHERE t1.started_at>=? AND t1.started_at<?",[$to,$from,$to])??0):null;
    $salesByDay=analytics_rows($pdo,"SELECT sr.business_date d,SUM(sr.total-sr.tax_amount) total,COUNT(*) receipts,COUNT(DISTINCT sr.session_id) bills FROM settlement_records sr WHERE $settlementWhere GROUP BY sr.business_date ORDER BY d",$settlementParams);
    $salesByHour=analytics_rows($pdo,"SELECT HOUR(sr.settled_at) h,SUM(sr.total-sr.tax_amount) total,COUNT(*) receipts,COUNT(DISTINCT sr.session_id) bills FROM settlement_records sr WHERE $settlementWhere GROUP BY HOUR(sr.settled_at) ORDER BY total DESC LIMIT 8",$settlementParams);
    $itemImpactSql="SELECT MAX(sale.item_name) item_name,SUM(sale.quantity) qty,SUM(sale.net_amount) revenue FROM settlement_records sr JOIN $saleLineSource ON sale.settlement_id=sr.id WHERE $settlementWhere GROUP BY CASE WHEN sale.item_id IS NULL THEN CONCAT('snapshot:',sale.item_name,'|',sale.unit_price) ELSE CONCAT('id:',sale.item_id) END ORDER BY revenue DESC,qty DESC";
    $topItems=analytics_rows($pdo,$itemImpactSql." LIMIT 12",$settlementParams);
    [$orderWhere,$orderParams]=analytics_snapshot_filter('o',$fromBusiness,$toBusiness,$selectedShift);[$waiterWhere,$waiterParams]=analytics_snapshot_filter('w',$fromBusiness,$toBusiness,$selectedShift);
    $orderQuality=analytics_rows($pdo,"SELECT COUNT(*) total,AVG(TIMESTAMPDIFF(SECOND,o.created_at,o.accepted_at)) avg_accept_sec FROM orders o WHERE $orderWhere AND o.accepted_at IS NOT NULL",$orderParams);
    $waiterQuality=analytics_rows($pdo,"SELECT COUNT(*) total,AVG(TIMESTAMPDIFF(SECOND,w.created_at,w.accepted_at)) avg_response_sec FROM waiter_calls w WHERE $waiterWhere AND w.accepted_at IS NOT NULL",$waiterParams);
    if(!$guestShiftLimited){$metrics=analytics_rows($pdo,"SELECT metric_key,SUM(metric_value) total FROM menu_metrics_daily WHERE metric_date>=? AND metric_date<=? GROUP BY metric_key",[$fromBusiness,$toBusiness]);$metricMap=[];foreach($metrics as $r)$metricMap[(string)$r['metric_key']]=(int)$r['total'];$searches=analytics_rows($pdo,"SELECT normalized_term,MAX(display_term) display_term,SUM(search_count) search_count,SUM(zero_result_count) zero_result_count FROM menu_search_terms_daily WHERE metric_date>=? AND metric_date<=? GROUP BY normalized_term ORDER BY search_count DESC LIMIT 12",[$fromBusiness,$toBusiness]);}else{$metricMap=[];$searches=[];}
}catch(Throwable $e){
    if($warning==='')$warning='بخشی از داده‌های تحلیلی در دسترس نیست. قبل از تصمیم مدیریتی، سلامت اطلاعات سامانه را بررسی کنید.';
    error_log('management analytics: '.$e->getMessage());$netSales=$prevSales=$taxTotal=$collectedTotal=$receiptCount=$billCount=$tableCount=0;$peakTables=null;$avgCheck=$avgSession=null;$salesByDay=$salesByHour=$topItems=$orderQuality=$waiterQuality=$searches=[];$metricMap=[];
}
$comparisonRows=[];
if($shiftScope==='compare'){
    foreach(business_report_shift_identities($shiftOptions) as $key=>$label){$where="$validSettlement AND sr.business_date>=? AND sr.business_date<=? AND sr.business_shift_key=?";$params=[$fromBusiness,$toBusiness,$key];$sales=(int)(analytics_scalar($pdo,"SELECT COALESCE(SUM(sr.total-sr.tax_amount),0) FROM settlement_records sr WHERE $where",$params)??0);$receipts=(int)(analytics_scalar($pdo,"SELECT COUNT(*) FROM settlement_records sr WHERE $where",$params)??0);$bills=(int)(analytics_scalar($pdo,"SELECT COUNT(DISTINCT sr.session_id) FROM settlement_records sr WHERE $where",$params)??0);[$ow,$op]=analytics_snapshot_filter('o',$fromBusiness,$toBusiness,$key);[$ww,$wp]=analytics_snapshot_filter('w',$fromBusiness,$toBusiness,$key);[$sw,$sp]=analytics_snapshot_filter('s',$fromBusiness,$toBusiness,$key);$comparisonRows[]=['label'=>$label,'sales'=>$sales,'receipts'=>$receipts,'bills'=>$bills,'avg'=>$bills?(int)round($sales/$bills):0,'orders'=>(int)(analytics_scalar($pdo,"SELECT COUNT(*) FROM orders o WHERE $ow",$op)??0),'calls'=>(int)(analytics_scalar($pdo,"SELECT COUNT(*) FROM waiter_calls w WHERE $ww",$wp)??0),'sessions'=>(int)(analytics_scalar($pdo,"SELECT COUNT(*) FROM table_sessions s WHERE $sw",$sp)??0)];}
}
$outsideActivity=['orders'=>0,'calls'=>0,'sessions'=>0,'settlements'=>0,'total'=>0];try{$outsideActivity=business_outside_activity_counts($fromBusiness,$toBusiness);}catch(Throwable $e){error_log('analytics outside-shift audit: '.$e->getMessage());}
$salesChange=$prevSales>0?round(($netSales-$prevSales)*100/$prevSales,1):null;$orderRow=$orderQuality[0]??[];$waiterRow=$waiterQuality[0]??[];
$menuViews=$metricMap['menu_view']??0;$itemAdds=$metricMap['item_add']??0;$orderSubmits=$metricMap['order_submit']??0;$searchTotal=array_sum(array_map(static fn(array $r):int=>(int)$r['search_count'],$searches));$zeroTotal=array_sum(array_map(static fn(array $r):int=>(int)$r['zero_result_count'],$searches));$zeroRate=$searchTotal>0?round($zeroTotal*100/$searchTotal,1):null;

if(($_GET['action']??'')==='export'){
    $itemGroupCountSql="SELECT COUNT(*) FROM (SELECT 1 FROM settlement_records sr JOIN $saleLineSource ON sale.settlement_id=sr.id WHERE $settlementWhere GROUP BY CASE WHEN sale.item_id IS NULL THEN CONCAT('snapshot:',sale.item_name,'|',sale.unit_price) ELSE CONCAT('id:',sale.item_id) END) grouped_items";$itemGroupCount=(int)(analytics_scalar($pdo,$itemGroupCountSql,$settlementParams)??0);try{report_export_guard($itemGroupCount,'اقلام فروش');}catch(RuntimeException $e){flash('warning',$e->getMessage());$query=$_GET;unset($query['action']);redirect('analytics.php'.($query?'?'.http_build_query($query):''));}$allItemRows=analytics_rows($pdo,$itemImpactSql,$settlementParams);
    $scope=$shiftOptions[$shiftScope]??'کل روز';
    $summary=[[xlsx_cell('فروش و عملکرد سکنا','title',3)],[xlsx_cell('بازه: '.$range['label'].' · '.$scope,'meta',3)],[xlsx_cell('شاخص','header'),xlsx_cell('مقدار','header'),xlsx_cell('توضیح','header')],['فروش پس از تخفیف (پیش از مالیات)',xlsx_cell($netSales,'money'),'تسویه‌های معتبر و برگشت‌نخورده'],['مالیات',xlsx_cell($taxTotal,'money'),'مالیات ثبت‌شده روی اسناد'],['دریافتی نهایی',xlsx_cell($collectedTotal,'money'),'فروش به‌علاوه مالیات'],['رسید پرداخت معتبر',xlsx_cell($receiptCount,'integer'),'هر پرداخت مستقل'],['حساب میز تسویه‌شده',xlsx_cell($billCount,'integer'),'تعداد نشست‌های دارای تسویه معتبر'],['میانگین حساب میز',$avgCheck===null?'—':xlsx_cell($avgCheck,'money'),''],['میانگین مدت نشست',$avgSession===null?'—':xlsx_cell((float)$avgSession,'integer'),'دقیقه'],['بیشترین میز هم‌زمان',$peakTables===null?'در این شیفت قابل محاسبه نیست':xlsx_cell($peakTables,'integer'),'برای کل روز قابل محاسبه است']];
    $daily=[[xlsx_cell('فروش روزانه','title',3)],[xlsx_cell('بازه: '.$range['label'],'meta',3)],[xlsx_cell('روز کاری','header'),xlsx_cell('رسید پرداخت','header'),xlsx_cell('فروش','header')]];foreach($salesByDay as $r)$daily[]=[jalali_date_input((string)$r['d']),xlsx_cell((int)$r['receipts'],'integer'),xlsx_cell((int)$r['total'],'money')];
    $items=[[xlsx_cell('اقلام فروش','title',3)],[xlsx_cell('بازه کامل · درآمد آیتم پس از تخصیص تخفیف و پیش از مالیات است.','meta',3)],[xlsx_cell('آیتم','header'),xlsx_cell('تعداد','header'),xlsx_cell('درآمد','header')]];foreach($allItemRows as $r)$items[]=[(string)$r['item_name'],xlsx_cell((int)$r['qty'],'integer'),xlsx_cell((int)$r['revenue'],'money')];
    $sheets=[['name'=>'خلاصه','rows'=>$summary,'widths'=>[30,24,50],'freeze_row'=>3],['name'=>'فروش روزانه','rows'=>$daily,'widths'=>[22,16,24],'freeze_row'=>3,'auto_filter'=>'A3:C'.max(3,count($daily))],['name'=>'اقلام','rows'=>$items,'widths'=>[34,16,24],'freeze_row'=>3,'auto_filter'=>'A3:C'.max(3,count($items))]];
    if($comparisonRows){$rows=[[xlsx_cell('مقایسه شیفت‌ها','title',7)],[xlsx_cell('بازه: '.$range['label'],'meta',7)],[xlsx_cell('شیفت','header'),xlsx_cell('فروش','header'),xlsx_cell('رسید','header'),xlsx_cell('میانگین حساب','header'),xlsx_cell('سفارش','header'),xlsx_cell('فراخوان','header'),xlsx_cell('نشست','header')]];foreach($comparisonRows as $r)$rows[]=[(string)$r['label'],xlsx_cell((int)$r['sales'],'money'),xlsx_cell((int)$r['receipts'],'integer'),xlsx_cell((int)$r['avg'],'money'),xlsx_cell((int)$r['orders'],'integer'),xlsx_cell((int)$r['calls'],'integer'),xlsx_cell((int)$r['sessions'],'integer')];$sheets[]=['name'=>'مقایسه شیفت‌ها','rows'=>$rows,'widths'=>[20,22,14,22,14,14,14],'freeze_row'=>3,'landscape'=>true];}
    xlsx_download('sokna-sales-performance.xlsx',$sheets);
}

panel_header('فروش و عملکرد','analytics');
?>
<div class="panel-surface-stack">
<section class="report-shell"><div class="report-shell-head"><div><strong>فروش و عملکرد</strong><small>برای تصمیم مدیریتی بازه‌ای؛ مبالغ تومان و مبنا روز عملیاتی کافه است.</small></div><span class="report-range-summary"><?= e((string)$range['label']) ?></span></div><form method="get" class="report-filter-grid"><?php report_render_range_fields($range,'analyticsReport'); ?><?php if($showShiftFilter): ?><div class="form-group"><label for="analyticsShift">شیفت</label><select class="form-control" id="analyticsShift" name="shift" data-choice-mode="adaptive" data-choice-label="شیفت"><?php foreach($shiftOptions as $key=>$label): ?><option value="<?= e($key) ?>" <?= $shiftScope===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><?php endif; ?><div class="report-filter-actions"><button class="btn btn-primary">نمایش</button><button class="btn btn-light" name="action" value="export">خروجی Excel</button></div></form></section>
