<?php if((int)$outsideActivity['total']>0): ?><div class="report-exception-strip"><strong><?= fa_digits((int)$outsideActivity['total']) ?> رخداد خارج از ساعت شیفت</strong><span>جزئیات در گزارش عملیات؛ این رخدادها از آمار کل روز حذف نشده‌اند.</span></div><?php endif; ?>
<section id="analyticsOverview"><div class="metric-grid compact-kpi-grid"><article class="metric-card"><span>فروش پس از تخفیف</span><strong><?= e(toman_number($netSales)) ?></strong><small><?= $salesChange===null?'مقایسه قبلی کافی نیست':($salesChange>=0?'+':'').analytics_number($salesChange,1).'٪ نسبت به بازه قبل' ?></small></article><article class="metric-card"><span>مالیات</span><strong><?= e(toman_number($taxTotal)) ?></strong><small>جزء فروش محسوب نمی‌شود</small></article><article class="metric-card"><span>دریافتی نهایی</span><strong><?= e(toman_number($collectedTotal)) ?></strong><small>فروش + مالیات</small></article><article class="metric-card"><span>رسید پرداخت</span><strong><?= e(fa_digits($receiptCount)) ?></strong><small>هر پرداخت مستقل</small></article><article class="metric-card"><span>حساب میز</span><strong><?= e(fa_digits($billCount)) ?></strong><small>نشست‌های تسویه‌شده</small></article><article class="metric-card"><span>میانگین حساب میز</span><strong><?= $avgCheck===null?'—':e(toman_number($avgCheck)) ?></strong></article><article class="metric-card"><span>میانگین مدت نشست</span><strong><?= $avgSession===null?'—':e(analytics_number($avgSession,0).' دقیقه') ?></strong></article></div></section>
<?php if($comparisonRows): ?><section class="card"><div class="card-head"><div><h2>مقایسه شیفت‌ها</h2><small>فروش بر اساس شیفت ثبت‌شده هنگام تسویه؛ رخدادها بر اساس اطلاعات ثبت‌شده همان زمان.</small></div></div><div class="report-data-list" style="--report-metric-count:6"><?php foreach($comparisonRows as $r): ?><article class="report-data-row"><div class="report-data-primary"><strong><?= e((string)$r['label']) ?></strong><small><?= fa_digits((int)$r['receipts']) ?> رسید · <?= fa_digits((int)$r['bills']) ?> حساب</small></div><div class="report-data-metric"><span>فروش</span><strong><?= e(toman_number((int)$r['sales'])) ?></strong></div><div class="report-data-metric"><span>میانگین حساب</span><strong><?= e(toman_number((int)$r['avg'])) ?></strong></div><div class="report-data-metric"><span>سفارش</span><strong><?= fa_digits((int)$r['orders']) ?></strong></div><div class="report-data-metric"><span>فراخوان</span><strong><?= fa_digits((int)$r['calls']) ?></strong></div><div class="report-data-metric"><span>نشست</span><strong><?= fa_digits((int)$r['sessions']) ?></strong></div></article><?php endforeach; ?></div></section><?php endif; ?>
<section class="analytics-grid" id="analyticsSales"><article class="card table-card"><div class="card-head"><div><h2>فروش روزانه</h2><small>فقط اسناد تسویه معتبر و برگشت‌نخورده.</small></div></div><div class="data-table-wrap"><table class="data-table analytics-compact-table"><thead><tr><th>روز کاری</th><th>رسید</th><th>فروش</th></tr></thead><tbody><?php foreach($salesByDay as $r): ?><tr><td><?= e(fa_digits(jalali_date_input((string)$r['d']))) ?></td><td><?= e(fa_digits((int)$r['receipts'])) ?></td><td class="analytics-money-cell"><?= e(toman_number((int)$r['total'])) ?></td></tr><?php endforeach; ?><?php if(!$salesByDay): ?><tr><td colspan="3" class="empty-state">داده‌ای نیست.</td></tr><?php endif; ?></tbody></table></div></article><article class="card"><div class="card-head"><div><h2>اقلام اثرگذار</h2><small>درآمد آیتم پس از تخصیص تخفیف و پیش از مالیات است؛ برای مقایسه اقلام استفاده شود.</small></div></div><div class="report-data-list" style="--report-metric-count:2"><?php foreach($topItems as $r): ?><article class="report-data-row"><div class="report-data-primary"><strong><?= e((string)$r['item_name']) ?></strong></div><div class="report-data-metric"><span>تعداد</span><strong><?= e(fa_digits((int)$r['qty'])) ?></strong></div><div class="report-data-metric"><span>درآمد</span><strong><?= e(toman_number((int)$r['revenue'])) ?></strong></div></article><?php endforeach; ?><?php if(!$topItems): ?><div class="empty-state">داده‌ای نیست.</div><?php endif; ?></div></article></section>
<section class="analytics-grid" id="analyticsTables"><article class="card"><div class="card-head"><div><h2>میزها و فشار ظرفیت</h2><small>بر اساس نشست‌های واقعی میزها در این بازه.</small></div></div><div class="card-body"><div class="metric-grid"><article class="metric-card"><span>میز فعال</span><strong><?= e(fa_digits($tableCount)) ?></strong></article><article class="metric-card"><span>بیشترین میز هم‌زمان</span><strong><?= $peakTables===null?'—':e(fa_digits($peakTables)) ?></strong><small><?= $peakTables===null?'برای شیفت انتخاب‌شده از داده فعلی قابل محاسبه نیست':($tableCount>0?analytics_number($peakTables*100/$tableCount,0).'٪ از میزهای فعال':'—') ?></small></article></div></div></article><article class="card table-card"><div class="card-head"><div><h2>ساعت‌های پرفروش</h2><small>برای تشخیص بازه‌های فشار.</small></div></div><div class="data-table-wrap"><table class="data-table analytics-compact-table"><thead><tr><th>ساعت</th><th>رسید</th><th>فروش</th></tr></thead><tbody><?php foreach($salesByHour as $r): ?><tr><td><?= e(fa_digits(sprintf('%02d:00',(int)$r['h']))) ?></td><td><?= e(fa_digits((int)$r['receipts'])) ?></td><td class="analytics-money-cell"><?= e(toman_number((int)$r['total'])) ?></td></tr><?php endforeach; ?><?php if(!$salesByHour): ?><tr><td colspan="3" class="empty-state">داده‌ای نیست.</td></tr><?php endif; ?></tbody></table></div></article></section>
<section class="analytics-grid" id="analyticsGuest"><article class="card"><div class="card-head"><div><h2>رفتار مهمان</h2><small>روزانه و بدون اطلاعات هویتی مهمان ثبت می‌شود.</small></div></div><div class="card-body"><?php if($guestShiftLimited): ?><div class="empty-state compact">این داده‌ها برای شیفت جداگانه ثبت نمی‌شوند؛ «کل روز» را انتخاب کن.</div><?php else: ?><div class="metric-grid"><article class="metric-card"><span>بازدید منو</span><strong><?= e(fa_digits($menuViews)) ?></strong></article><article class="metric-card"><span>افزودن به سبد</span><strong><?= e(fa_digits($itemAdds)) ?></strong></article><article class="metric-card"><span>رویداد ثبت سفارش</span><strong><?= e(fa_digits($orderSubmits)) ?></strong></article><article class="metric-card"><span>جست‌وجوی بی‌نتیجه</span><strong><?= $zeroRate===null?'—':e(analytics_number($zeroRate,1).'٪') ?></strong></article></div><?php endif; ?></div></article><article class="card table-card"><div class="card-head"><div><h2>عبارت‌های جست‌وجو</h2><small>برای نام‌گذاری، برچسب و تشخیص نیاز پیدا نشده.</small></div></div><div class="data-table-wrap"><table class="data-table analytics-compact-table"><thead><tr><th>عبارت</th><th>جست‌وجو</th><th>بی‌نتیجه</th></tr></thead><tbody><?php foreach($searches as $r): ?><tr><td><?= e((string)$r['display_term']) ?></td><td><?= e(fa_digits((int)$r['search_count'])) ?></td><td><?= e(fa_digits((int)$r['zero_result_count'])) ?></td></tr><?php endforeach; ?><?php if(!$searches): ?><tr><td colspan="3" class="empty-state">داده‌ای برای این نمایش وجود ندارد.</td></tr><?php endif; ?></tbody></table></div></article></section>
